#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using MVZ2.IO;
using UnityEngine;

namespace MVZ2.Debugs
{
    public class MVZ2Logger : MonoBehaviour
    {
        public bool ExportLogFilePack(string destPath)
        {
            var dir = Application.persistentDataPath;
            if (!Directory.Exists(dir))
                return false;

            CloneCurrentLog();

            try
            {
                FileHelper.ValidateDirectory(destPath);
                var sourceDirInfo = new DirectoryInfo(dir);
                var files = new string[]
                {
                    GetLogClonePath(),
                    GetPrevLogPath(),
                };
                using var stream = File.Open(destPath, FileMode.Create);
                using var archive = new ZipArchive(stream, ZipArchiveMode.Create);

                foreach (var filePath in files)
                {
                    if (!File.Exists(filePath))
                        continue;
                    var entryName = Path.GetRelativePath(dir, filePath);
                    entryName = entryName.Replace("\\", "/");
                    archive.CreateEntryFromFile(filePath, entryName);
                }
            }
            finally
            {
                DeleteLogClone();
            }
            return true;
        }

        #region 生命周期
        void OnEnable()
        {
            Application.logMessageReceivedThreaded += OnLogReceivedCallback;
        }
        void OnDisable()
        {
            Application.logMessageReceivedThreaded -= OnLogReceivedCallback;
        }
        private void Awake()
        {
            if (Instance && Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            Instance = this;
            DontDestroyOnLoad(gameObject);

            string path = GetLogPath();
            // 开启游戏时将上一次的日志前缀加上-prev。
            if (File.Exists(path))
            {
                string prevPath = GetPrevLogPath();
                if (File.Exists(prevPath))
                {
                    File.Delete(prevPath);
                }
                File.Move(path, prevPath);
            }
            StartLogWriter(path);
        }
        private void Update()
        {
            lock (logLock)
            {
                if (pendingLogs.Count == 0)
                    return;

                writeBuffer.Clear();

                writeBuffer.AddRange(pendingLogs);
                pendingLogs.Clear();
            }

            lock (logExportLock)
            {
                if (logWriter == null)
                {
                    StartLogWriter(GetLogPath());
                }

                if (logWriter == null)
                    return;

                foreach (var log in writeBuffer)
                {
                    logWriter.WriteLine(log);
                }

                logWriter.Flush();
            }
        }
#if UNITY_ANDROID || UNITY_IOS
        private void OnApplicationFocus(bool focus)
        {
            // 安卓失去焦点后，关闭文件流。
            // 因为安卓切换到其他应用时，可能会在后台被系统施放，而不调用OnApplicationQuit.
            if (!focus)
            {
                CloseLogWriter();
            }
            else
            {
                StartLogWriter(GetLogPath());
            }
        }
#endif
        private void OnApplicationQuit()
        {
            // 退出游戏后，关闭文件流。
            CloseLogWriter();
        }
        #endregion

        #region 事件回调
        void OnLogReceivedCallback(string logString, string stackTrace, LogType type)
        {
            lock (logLock)
            {
                string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                pendingLogs.Add($"[{timestamp}][{type}]{logString}\n{stackTrace}\n\n");
            }
        }
        #endregion

        #region 输出日志内容
        private string GetLogPath()
        {
            return Path.Combine(Application.persistentDataPath, $"{fileName}{extension}");
        }
        private string GetPrevLogPath()
        {
            return Path.Combine(Application.persistentDataPath, $"{fileName}{prevSuffix}{extension}");
        }
        private string GetLogClonePath()
        {
            return Path.Combine(Application.persistentDataPath, $"{fileName}{cloneSuffix}{extension}");
        }
        #endregion

        #region LogWriter
        private void StartLogWriter(string path)
        {
            lock (logExportLock)
            {
                if (logWriter == null)
                {
                    logWriter = new StreamWriter(path, true);
                }
            }
        }
        private void CloseLogWriter()
        {
            lock (logExportLock)
            {
                if (logWriter != null)
                {
                    logWriter.Dispose();
                    logWriter = null;
                }
            }
        }
        #endregion

        #region 导出日志
        private void CloneCurrentLog()
        {
            lock (logExportLock)
            {
                CloseLogWriter();

                DeleteLogClone();
                var currentLogPath = GetLogPath();
                if (File.Exists(currentLogPath))
                {
                    var cloneLogPath = GetLogClonePath();
                    File.Copy(currentLogPath, cloneLogPath);
                }
                StartLogWriter(currentLogPath);
            }
        }
        private void DeleteLogClone()
        {
            var cloneLogPath = GetLogClonePath();
            if (!File.Exists(cloneLogPath))
                return;
            File.Delete(cloneLogPath);
        }
        #endregion

        public static MVZ2Logger Instance { get; private set; } = null!;
        [SerializeField]
        string fileName = "mvz2_log";
        [SerializeField]
        string cloneSuffix = "-current";
        [SerializeField]
        string prevSuffix = "-prev";
        [SerializeField]
        string extension = ".log";
        StreamWriter? logWriter;
        private readonly List<string> pendingLogs = new();
        private readonly List<string> writeBuffer = new();
        readonly object logLock = new object();
        readonly object logExportLock = new object();
    }
}
